sales = pd.read_excel("data/sales_q3.xlsx")
summary = sales.groupby("region")[["revenue", "revenue_2025Q3"]].sum()
summary["growth"] = summary["revenue"] / summary["revenue_2025Q3"] - 1
summary.to_csv("output/q3-by-region.csv")
